import numpy as np
from sklearn.linear_model import Ridge
from sklearn.ensemble import HistGradientBoostingRegressor

class RidgeBoost:
    def __init__(self, params, seed):
        self.p = params
        self.seed = seed
    def fit(self, X, y):
        y = np.asarray(y)
        if y.ndim == 1:
            y = y[:, None]
        self.r = Ridge(alpha=self.p.get('alpha', 1.0)).fit(X, y)
        res = y - self.r.predict(X).reshape(y.shape)
        self.b = []
        for j in range(y.shape[1]):
            m = HistGradientBoostingRegressor(learning_rate=self.p.get('learning_rate', 0.05), max_iter=int(self.p.get('max_iter', 300)), max_leaf_nodes=int(self.p.get('max_leaf_nodes', 15)), l2_regularization=self.p.get('l2_regularization', 1.0), early_stopping=True, validation_fraction=0.1, random_state=self.seed)
            m.fit(X, res[:, j])
            self.b.append(m)
        self.single = (np.asarray(y).shape[1] == 1)
        return self
    def predict(self, X):
        base = self.r.predict(X)
        if base.ndim == 1:
            base = base[:, None]
        corr = np.column_stack([m.predict(X) for m in self.b])
        out = base + corr
        return out[:, 0] if self.single else out
    def get_params(self, deep=True):
        return {'params': self.p, 'seed': self.seed}
    def set_params(self, **kw):
        for k, v in kw.items():
            setattr(self, 'p' if k == 'params' else k, v)
        return self

def build_model(params, task, seed):
    return RidgeBoost(params, seed)

import numpy as np
from sklearn.base import BaseEstimator, RegressorMixin
from sklearn.preprocessing import StandardScaler
from sklearn.kernel_ridge import KernelRidge

def _feats(X):
    X = np.asarray(X, dtype=float)
    n = X.shape[0]
    scale = np.median(np.abs(X)) + 1e-12
    L = np.log(np.clip(np.abs(X), 1e-3 * scale, None))
    out = [X, L]
    if X.shape[1] == 80:
        for shape in [(4, 20), (20, 4)]:
            A = L.reshape(n, *shape)
            B = A if shape == (4, 20) else A.transpose(0, 2, 1)
            out.append(np.diff(B, axis=2).reshape(n, -1))
            out.append(np.diff(B, axis=1).reshape(n, -1))
    return np.hstack(out)

class PhysKRR(BaseEstimator, RegressorMixin):
    def __init__(self, alpha=1e-3, gamma_mult=0.5):
        self.alpha = alpha
        self.gamma_mult = gamma_mult
    def fit(self, X, y):
        F = _feats(X)
        self.sc_ = StandardScaler().fit(F)
        Fs = np.nan_to_num(self.sc_.transform(F))
        g = self.gamma_mult / Fs.shape[1]
        self.m_ = KernelRidge(alpha=self.alpha, kernel='rbf', gamma=g).fit(Fs, y)
        return self
    def predict(self, X):
        Fs = np.nan_to_num(self.sc_.transform(_feats(X)))
        return self.m_.predict(Fs)

def build_model(params, task, seed):
    return PhysKRR(alpha=float(params.get('alpha', 1e-3)), gamma_mult=float(params.get('gamma_mult', 0.5)))

